// Composing with YuE2 (github.com/multimodal-art-projection/YuE): its plan() step turns a style
// prompt and lyrics into a melody-and-chord score in ABC, which abcToScore turns into a JingleScript
// score. Only plan() runs (no audio is generated by YuE2); JingleScript plays the score.
//
// YuE2 is an external engine, located like NEUTRINO and never bundled: YUE2_PYTHON (in the
// environment, or in .env in the current directory) names a Python that has `yue2` installed and
// the m-a-p/YuE2-3B weights in its Hugging Face cache. Nothing is downloaded from here.
//
// Unlike rendering, composing is NOT deterministic across machines: YuE2 samples on a GPU, and its
// own docs say other GPUs or runtime versions change a seeded result. Keep the score it produced;
// the score then renders bit-identically like any other.
import { spawn } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { parseEnv } from "node:util";
import { z } from "zod";
import { phrasesIn, placeLyrics, type PhraseFit } from "./abc-lyrics.ts";
import { abcToScore, parseAbc, sectionNames, type AbcToScoreOptions } from "./abc.ts";
import type { Score } from "./score.ts";

const SETUP = `Set it up yourself (YuE2's code is Apache-2.0; its weights are CC BY-NC 4.0 with a creator permission — companies need a licence from the authors):
  uv venv --python 3.12 ~/yue2-venv
  uv pip install --python ~/yue2-venv/bin/python git+https://github.com/multimodal-art-projection/YuE
  ~/yue2-venv/bin/python -c 'from yue2.storage import resolve_model; [resolve_model(m) for m in ("m-a-p/YuE2-3B", "m-a-p/YuE2-Vae")]'
then put YUE2_PYTHON=~/yue2-venv/bin/python (the full path) in .env in the project directory (or in the environment).`;

/** YuE2 is not set up where this runs. */
export class Yue2MissingError extends Error {
  constructor(problem: string) {
    super(`YuE2 is not available: ${problem}\n${SETUP}`);
    this.name = "Yue2MissingError";
  }
}

/** YuE2 ran but did not produce a score. */
export class Yue2Error extends Error {
  constructor(message: string) {
    super(message);
    this.name = "Yue2Error";
  }
}

/** The Python to run YuE2 with: YUE2_PYTHON from the environment, else from `envFile`. */
export function yue2Python(env: NodeJS.ProcessEnv = process.env, envFile = join(process.cwd(), ".env")): string | undefined {
  if (env.YUE2_PYTHON) return env.YUE2_PYTHON;
  return existsSync(envFile) ? parseEnv(readFileSync(envFile, "utf8")).YUE2_PYTHON || undefined : undefined;
}

const MISSING_IMPORT = 3;
const MISSING_WEIGHTS = 4;

// Run with `python -I -c`; reads the request as JSON on stdin, writes the result as JSON on stdout.
// YuE2's own progress goes to stderr.
const PLAN_SCRIPT = String.raw`
import json, sys, time
try:
    from yue2 import YuE2Pipeline
except Exception as e:
    print(f"cannot import yue2: {e}", file=sys.stderr); sys.exit(${MISSING_IMPORT})
job = json.load(sys.stdin)
try:
    pipe = YuE2Pipeline.from_pretrained(job["model"], device=job["device"], backend="torch-eager", local_files_only=True)
except Exception as e:
    if type(e).__name__ in ("LocalEntryNotFoundError", "OfflineModeIsEnabled", "FileNotFoundError", "EntryNotFoundError"):
        print(f"the {job['model']} weights are not downloaded: {e}", file=sys.stderr); sys.exit(${MISSING_WEIGHTS})
    raise
start = time.perf_counter()
plan = pipe.plan(**job["request"])
json.dump({"abc": plan.abc, "truncated": plan.truncated, "tokens": len(plan.abc_ids), "seconds": time.perf_counter() - start}, sys.stdout)
`;

const PlanOutputSchema = z.object({ abc: z.string().min(1), truncated: z.boolean(), tokens: z.number(), seconds: z.number() });

export type Yue2Plan = z.infer<typeof PlanOutputSchema>;

export interface Yue2Request {
  /** Genre, instruments, voice, language and tempo, e.g. "Japanese, bright children's TV jingle, marimba, 120 BPM". */
  style: string;
  /** Section tags and words: "[Chorus]\nハテナマルモ はじまるよ". */
  lyrics: string;
  /** YuE2's sampling seed (default 1). */
  seed?: number;
  /** "full" plans melody and chords (default); "melody" plans the melody only. */
  cot?: "full" | "melody";
}

export interface Yue2RunOptions {
  /** Overrides YUE2_PYTHON. */
  python?: string;
  /** "auto" (default), "mps", "cuda", "cpu". YUE2_DEVICE overrides the default. */
  device?: string;
  /** Default "m-a-p/YuE2-3B". */
  model?: string;
  /** Each progress line YuE2 prints ("[YuE2] Running Planning score: 152 tokens …"). */
  onProgress?: (line: string) => void;
  signal?: AbortSignal;
}

interface Finished {
  code: number | null;
  stdout: string;
  stderr: string;
}

function runPython(python: string, input: string, options: Yue2RunOptions): Promise<Finished> {
  return new Promise((resolve, reject) => {
    const child = spawn(python, ["-I", "-c", PLAN_SCRIPT], { stdio: ["pipe", "pipe", "pipe"], signal: options.signal });
    let stdout = "";
    let stderr = "";
    let pending = "";
    child.stdout.on("data", (chunk: Buffer) => (stdout += chunk.toString("utf8")));
    child.stderr.on("data", (chunk: Buffer) => {
      const text = chunk.toString("utf8");
      stderr += text;
      pending += text;
      const lines = pending.split(/\r?\n|\r/);
      pending = lines.pop() ?? "";
      for (const line of lines) if (line.trim() !== "") options.onProgress?.(line);
    });
    child.on("error", (error: Error & { code?: string }) => {
      if (error.code === "ENOENT") reject(new Yue2MissingError(`${python} does not exist.`));
      else reject(error);
    });
    child.on("close", (code) => resolve({ code, stdout, stderr }));
    child.stdin.end(input);
  });
}

/** Runs YuE2's plan(): a style and lyrics in, YuE2's native ABC out. Takes 20–40 s on an M2 Max. */
export async function planWithYuE2(request: Yue2Request, options: Yue2RunOptions = {}): Promise<Yue2Plan> {
  const python = options.python ?? yue2Python() ?? "";
  if (python === "") throw new Yue2MissingError("YUE2_PYTHON is not set.");
  const job = {
    model: options.model ?? "m-a-p/YuE2-3B",
    device: options.device ?? process.env.YUE2_DEVICE ?? "auto",
    request: { id: "jinglescript", style: request.style, lyrics: request.lyrics, seed: request.seed ?? 1, cot: request.cot ?? "full" },
  };
  const { code, stdout, stderr } = await runPython(python, JSON.stringify(job), options);
  const lastLine = stderr.trim().split("\n").at(-1) ?? "";
  if (code === MISSING_IMPORT || code === MISSING_WEIGHTS) throw new Yue2MissingError(lastLine);
  if (code !== 0) throw new Yue2Error(`YuE2's plan() failed (exit ${code}):\n${stderr.trim().split("\n").slice(-8).join("\n")}`);
  const output = PlanOutputSchema.safeParse(JSON.parse(stdout));
  if (!output.success) throw new Yue2Error(`YuE2 returned no score: ${output.error.message}`);
  return output.data;
}

export interface ComposeOptions extends Yue2Request, AbcToScoreOptions, Yue2RunOptions {}

export interface Composition {
  score: Score;
  /** YuE2's ABC as it wrote it (the whole song, even when `section` kept one part). */
  abc: string;
  /** The song's sections, as cue names `section` accepts. */
  sections: string[];
  plan: Yue2Plan;
  /** How the lyrics went onto the phrases of the melody kept (empty when they were not placed). */
  lyrics: PhraseFit[];
  /** Why the lyrics were not placed on the notes (they are not kana and nothing is sung). */
  lyricsSkipped?: string;
}

/** Composes with YuE2's plan() and returns a JingleScript score playing it (see abcToScore). */
export async function compose(options: ComposeOptions): Promise<Composition> {
  const plan = await planWithYuE2(options, options);
  const whole = parseAbc(plan.abc);
  const placed = placeLyrics(whole, options.lyrics, options.sing !== undefined);
  const score = abcToScore(placed.parsed, { ...options, seed: options.seed ?? 1 });
  const skipped = placed.skipped === undefined ? {} : { lyricsSkipped: placed.skipped };
  return { score, abc: plan.abc, sections: sectionNames(whole), plan, lyrics: phrasesIn(placed.phrases, whole, options.section), ...skipped };
}
